from __future__ import annotations
import argparse, base64, concurrent.futures, fcntl, gzip, hashlib, json, os
from pathlib import Path, PurePosixPath
import shutil, stat, sys, tempfile, time, traceback, zipfile

PAYLOAD_BASE64 = ""
PAYLOAD_SHA256 = "b22837b87c078c825ccbf6d0a61deffb9304e2064111da91a9f54a6b3ec56bc3"

def emit(kind, **values):
    print(json.dumps({"event": kind, **values}, ensure_ascii=False, sort_keys=True), flush=True)

def main():
    parser = argparse.ArgumentParser(description="Continue original nine-tile 3DEP source acquisition1330; no GIS or model execution.")
    parser.add_argument("--root", type=Path, required=True)
    parser.add_argument("--workers", type=int, default=2, choices=range(1,3))
    args = parser.parse_args()
    root = args.root.resolve()
    root.mkdir(parents=True, exist_ok=True)
    lock = (root / ".original-terrain1330.lock").open("a+b")
    try:
        fcntl.flock(lock.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
    except BlockingIOError:
        raise RuntimeError("This original terrain source operation already has an active writer at " + str(root))
    raw = gzip.decompress(base64.b64decode(PAYLOAD_BASE64, validate=True))
    if hashlib.sha256(raw).hexdigest() != PAYLOAD_SHA256:
        raise ValueError("Original source payload hash differs")
    payload = json.loads(raw)
    if payload["operation"] != "ECSA-UPPER-SAVANNAH-TERRAIN-20261013":
        raise ValueError("Original operation identity differs")
    source_root = root / "source"
    expected = []
    for member in payload["files"]:
        relative = PurePosixPath(member["path"])
        if relative.is_absolute() or ".." in relative.parts or "\\" in member["path"] or relative.as_posix() != member["path"]:
            raise ValueError("Source member is not canonical")
        data = member["content"].encode("utf-8")
        if len(data) != member["bytes"] or hashlib.sha256(data).hexdigest() != member["sha256"]:
            raise ValueError("Original source member differs: " + member["path"])
        target = source_root.joinpath(*relative.parts)
        if not target.resolve().is_relative_to(source_root.resolve()):
            raise ValueError("Source member escapes receiving root")
        if target.exists() and (target.is_symlink() or target.read_bytes() != data):
            raise ValueError("Retained source preimage differs: " + member["path"])
        expected.append((target, data))
    for target, data in expected:
        target.parent.mkdir(parents=True, exist_ok=True)
        if not target.exists():
            fd, staged_name = tempfile.mkstemp(prefix=".source-", suffix=".partial", dir=target.parent)
            staged = Path(staged_name)
            try:
                with os.fdopen(fd,"wb") as stream:
                    stream.write(data)
                    stream.flush()
                    os.fsync(stream.fileno())
                try:
                    os.link(staged,target)
                except FileExistsError:
                    if target.is_symlink() or target.read_bytes() != data:
                        raise ValueError("Concurrent source preimage differs: " + str(target))
                dir_fd = os.open(target.parent,os.O_RDONLY|getattr(os,"O_DIRECTORY",0))
                try:
                    os.fsync(dir_fd)
                finally:
                    os.close(dir_fd)
            finally:
                staged.unlink(missing_ok=True)
    sys.path.insert(0, str(source_root))
    from source_tools.terrain_io import atomic_bytes, atomic_json, capture, describe, file_sha, now, read_json
    state_path = root / "source-receiving.json"
    archive = root / "Upper_Savannah_Original_3DEP_Nine_Tiles_20261013.zip"
    archive_receipt = root / "archive-ready.json"
    if archive.exists():
        if archive.is_symlink() or not archive.is_file():
            raise ValueError("Published terrain archive must be a retained regular file")
        with zipfile.ZipFile(archive) as opened:
            names = opened.namelist()
            if len(names) != len(set(names)):
                raise ValueError("Published terrain archive contains duplicate names")
            for item in opened.infolist():
                name = PurePosixPath(item.filename)
                if name.is_absolute() or ".." in name.parts or "\\" in item.filename or name.as_posix() != item.filename or stat.S_ISLNK(item.external_attr >> 16):
                    raise ValueError("Published terrain archive contains a noncanonical member")
            for member in payload["files"]:
                body = opened.read("source/"+member["path"])
                if len(body) != member["bytes"] or hashlib.sha256(body).hexdigest() != member["sha256"]:
                    raise ValueError("Published terrain archive has a different original source member")
            retained_receipt = opened.read("source-receiving.json")
            saved_state = json.loads(retained_receipt)
            if (saved_state.get("operation") != payload["operation"] or
                    saved_state.get("source_payload_sha256") != PAYLOAD_SHA256 or
                    saved_state.get("state") != "originals_complete" or
                    len(saved_state.get("members",[])) != 27 or saved_state.get("tiff_count") != 9):
                raise ValueError("Published terrain archive belongs to an incomplete/different source edition")
            inventory = json.loads(opened.read("source/source/terrain/20261013/inventory.json"))
            assets = {(tile["tile"],item["name"]):(item,tile) for tile in inventory["tiles"] for item in tile["assets"]}
            received_keys = set()
            for member in saved_state["members"]:
                key = (member["tile"],member["name"])
                if key not in assets or key in received_keys:
                    raise ValueError("Published terrain archive source selection differs")
                received_keys.add(key)
                asset, tile = assets[key]
                expected_path = "terrain-store/receiving/"+key[0]+"/"+key[1]
                if member["url"] != asset["url"] or member["body"]["path"] != expected_path or member["http"]["path"] != expected_path+".http.json":
                    raise ValueError("Published terrain source path or origin differs")
                for record in (member["body"],member["http"]):
                    digest = hashlib.sha256()
                    count = 0
                    with opened.open(record["path"]) as stream:
                        for block in iter(lambda:stream.read(1024*1024),b""):
                            digest.update(block)
                            count += len(block)
                    if count != record["bytes"] or digest.hexdigest() != record["sha256"]:
                        raise ValueError("Published original terrain member differs from its source receipt")
                http = json.loads(opened.read(member["http"]["path"]))
                if http.get("state") != "complete" or http.get("url") != asset["url"] or http.get("bytes") != member["body"]["bytes"] or http.get("sha256") != member["body"]["sha256"]:
                    raise ValueError("Published original terrain HTTP identity differs")
                if member["body"]["bytes"] != asset["listed_bytes"] or (key[1].endswith(".xml") and member["body"]["sha256"] != tile["metadata_sha256"]):
                    raise ValueError("Published original terrain inventory identity differs")
            if received_keys != set(assets):
                raise ValueError("Published original terrain source members are incomplete")
            tiff_bytes = sum(row["body"]["bytes"] for row in saved_state["members"] if row["name"].endswith(".tif"))
            if tiff_bytes != saved_state.get("tiff_bytes"):
                raise ValueError("Published original TIFF byte total differs")
        restored = {"operation":payload["operation"],"source_payload_sha256":PAYLOAD_SHA256,
                    "path":str(archive),"bytes":archive.stat().st_size,"sha256":file_sha(archive),
                    "source_receiving":str(state_path),"members":27,"tiffs":9,
                    "tiff_bytes":tiff_bytes,"numeric_admission":"pending_original_GIS_consumer"}
        if archive_receipt.exists() and read_json(archive_receipt) != restored:
            raise ValueError("Existing published archive-ready receipt differs; original archive preserved")
        if state_path.exists() and state_path.read_bytes() != retained_receipt:
            prior_receipt = state_path.read_bytes()
            atomic_bytes(root / ("source-receiving-before-recovery-"+hashlib.sha256(prior_receipt).hexdigest()+".json"),prior_receipt,immutable=True)
        atomic_bytes(state_path,retained_receipt)
        atomic_json(archive_receipt,restored,immutable=True)
        emit("archive_ready",reused=True,**restored)
        fcntl.flock(lock.fileno(),fcntl.LOCK_UN)
        lock.close()
        return 0
    if archive_receipt.exists():
        raise ValueError("Published archive receipt exists but its original archive is missing; do not rebuild silently")
    prior = read_json(state_path) if state_path.exists() else None
    if prior and (prior.get("operation") != payload["operation"] or prior.get("source_payload_sha256") != PAYLOAD_SHA256):
        raise ValueError("This root already belongs to another retained source edition")
    state = {"schema": "upstate.terrain-original-receiving/v1",
             "operation": payload["operation"], "original_request": payload["original_request"],
             "source_payload_sha256": PAYLOAD_SHA256, "runtime_sources": payload["runtime_sources"],
             "pid": os.getpid(), "root": str(root), "state": "receiving",
             "started_at": now(), "members": [], "errors": [],
             "numeric_admission": "pending_original_GIS_consumer",
             "scientific_note": "Full original publisher bodies only. No raster crop, resampling, DEM conditioning or model run."}
    atomic_json(state_path, state)
    emit("started", pid=os.getpid(), root=str(root), receipt=str(state_path),
         free_bytes=shutil.disk_usage(root).free)
    try:
        inventory_path = source_root / "source/terrain/20261013/inventory.json"
        inventory = read_json(inventory_path)
        original = {tile["tile"]:tile for tile in inventory["tiles"]}
        store = root / "terrain-store"
        if len(original) != 9 or sum(len(tile["assets"]) for tile in original.values()) != 27:
            raise ValueError("Original retained inventory does not select nine complete degree tiles")
        tasks = []
        for tile_id, retained in sorted(original.items()):
            if {asset["name"] for asset in retained["assets"]} != {"USGS_1_"+tile_id+ext for ext in (".tif",".xml",".gpkg")}:
                raise ValueError("Original terrain companion set differs: " + tile_id)
            for asset in sorted(retained["assets"],key=lambda item:item["name"]):
                tasks.append((tile_id, asset["name"], asset, retained))
        state["selection_basis"] = "Exact retained original inventory URLs; no live directory discovery prerequisite."
        state["original_inventory"] = describe(root, inventory_path)
        atomic_json(state_path, state)
        def receive(item):
            tile_id, name, asset, retained = item
            destination = store / "receiving" / tile_id / name
            response = capture(asset["url"], destination,
                               maximum_bytes=16*1024*1024 if name.endswith(".xml") else None)
            record = {"tile":tile_id, "name":name, "url":asset["url"],
                      "body":describe(root,destination),
                      "http":describe(root,destination.with_name(destination.name+".http.json")),
                      "listed_bytes":asset["listed_bytes"],
                      "listed_bytes_match":response["bytes"] == asset["listed_bytes"]}
            if name.endswith(".xml"):
                record["original_metadata_sha256"] = retained["metadata_sha256"]
                record["original_metadata_matches"] = response["sha256"] == retained["metadata_sha256"]
            return record
        with concurrent.futures.ThreadPoolExecutor(max_workers=args.workers) as pool:
            futures = {pool.submit(receive, item):item for item in tasks}
            for future in concurrent.futures.as_completed(futures):
                item = futures[future]
                try:
                    record = future.result()
                    state["members"].append(record)
                    emit("original_received", **record)
                    if not record["listed_bytes_match"] or record.get("original_metadata_matches") is False:
                        state["errors"].append({"tile":item[0],"name":item[1],
                           "error":"Current publisher entity differs from retained inventory. Original and current bytes are retained; do not call this the frozen edition."})
                except Exception as error:
                    failure = {"tile":item[0],"name":item[1],"error":type(error).__name__+": "+str(error)}
                    state["errors"].append(failure)
                    emit("source_error", **failure)
                state["updated_at"] = now()
                atomic_json(state_path, state)
        state["members"].sort(key=lambda row:(row["tile"],row["name"]))
        state["tiff_count"] = sum(row["name"].endswith(".tif") for row in state["members"])
        state["tiff_bytes"] = sum(row["body"]["bytes"] for row in state["members"] if row["name"].endswith(".tif"))
        if state["errors"] or len(state["members"]) != 27 or state["tiff_count"] != 9:
            state["state"] = "interrupted"
            atomic_json(state_path,state)
            emit("interrupted", receipt=str(state_path), errors=state["errors"])
            return 1
        state["state"] = "originals_complete"
        state["completed_at"] = now()
        atomic_json(state_path,state)
        emit("originals_complete", receipt=str(state_path), members=27, tiffs=9,
             tiff_bytes=state["tiff_bytes"])
        pending = archive.with_name(archive.name + ".partial")
        members = [*source_root.rglob("*"),*store.rglob("*"),state_path]
        driver = Path(__file__).resolve(strict=True)
        with zipfile.ZipFile(pending,"w",compression=zipfile.ZIP_STORED,allowZip64=True) as out:
            for path in sorted(members):
                if path.is_file() and not path.is_symlink() and path.suffix not in (".lock",".partial",".pyc") and "__pycache__" not in path.parts:
                    out.write(path,path.relative_to(root).as_posix())
            out.write(driver,"receive-original-terrain1330.py")
        with zipfile.ZipFile(pending) as check:
            if check.testzip() is not None:
                raise ValueError("Complete original terrain archive CRC check failed")
        os.replace(pending,archive)
        receipt = {"operation":payload["operation"],"source_payload_sha256":PAYLOAD_SHA256,
                   "path":str(archive),"bytes":archive.stat().st_size,"sha256":file_sha(archive),
                   "source_receiving":str(state_path),"members":27,"tiffs":9,
                   "tiff_bytes":state["tiff_bytes"],"numeric_admission":"pending_original_GIS_consumer"}
        atomic_json(archive_receipt,receipt)
        emit("archive_ready",**receipt)
        return 0
    except BaseException as error:
        state["state"] = "failed"
        state["error"] = type(error).__name__+": "+str(error)
        state["updated_at"] = now()
        try:
            atomic_json(state_path,state)
        except OSError as receipt_error:
            emit("receipt_write_failed",error=type(receipt_error).__name__+": "+str(receipt_error))
        emit("failed",receipt=str(state_path),error=state["error"])
        raise
    finally:
        fcntl.flock(lock.fileno(),fcntl.LOCK_UN)
        lock.close()

if __name__ == "__main__":
    raise SystemExit(main())
